// Package: OpenTelemetry
// Package: Microsoft.Extensions.AI
// Package: Microsoft.Extensions.AI.OpenTelemetry --version 9.*

using System.Diagnostics;
using System.Diagnostics.Metrics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.OpenTelemetry;

public sealed class TracedRagPipeline
{
    private static readonly ActivitySource ActivitySource = new("RagPipeline");
    private static readonly Meter Meter = new("RagPipeline");
    private static readonly Counter<long> RequestCounter = Meter.CreateCounter<long>("rag.requests");
    private static readonly Histogram<double> LatencyHistogram = Meter.CreateHistogram<double>("rag.latency_ms");

    private readonly IEmbeddingGenerator _embeddingGenerator;
    private readonly IVectorStore _vectorStore;
    private readonly IChatClient _chatClient;

    public TracedRagPipeline(
        IEmbeddingGenerator embeddingGenerator,
        IVectorStore vectorStore,
        IChatClient chatClient)
    {
        _embeddingGenerator = embeddingGenerator;
        _vectorStore = vectorStore;
        _chatClient = chatClient;
    }

    public async Task<string> QueryAsync(string question, CancellationToken ct = default)
    {
        using var activity = ActivitySource.StartActivity("rag.query", ActivityKind.Server);
        activity?.SetTag("rag.question", question);

        var start = Stopwatch.GetTimestamp();
        RequestCounter.Add(1);

        try
        {
            // Embed the question
            using var embedActivity = ActivitySource.StartActivity("rag.embed");
            var embedding = await _embeddingGenerator.GenerateAsync(question, ct);
            embedActivity?.SetTag("rag.embedding_dimensions", embedding.Vector.Length);

            // Retrieve chunks
            using var retrieveActivity = ActivitySource.StartActivity("rag.retrieve");
            var chunks = await _vectorStore.SearchAsync<VectorStoreRecord>(
                "rag-documents",
                embedding.Vector,
                new VectorSearchOptions { Top = 5 },
                ct);
            retrieveActivity?.SetTag("rag.chunks_retrieved", chunks.Count());

            // Generate answer
            using var generateActivity = ActivitySource.StartActivity("rag.generate");
            var prompt = BuildPrompt(question, chunks);
            var response = await _chatClient.GetResponseAsync(
                new[] { new ChatMessage(ChatRole.User, prompt) },
                cancellationToken: ct);
            generateActivity?.SetTag("rag.completion_tokens", response.Messages.Last().Text?.Length ?? 0);

            var answer = response.Messages.Last().Text ?? string.Empty;
            activity?.SetTag("rag.answer_length", answer.Length);

            // Expected output in Jaeger/Application Insights:
            //   Trace: rag.query -> rag.embed -> rag.retrieve -> rag.generate
            //   Metrics: rag.requests=1, rag.latency_ms=~250
            //   Attributes: question, embedding_dimensions, chunks_retrieved, completion_tokens

            return answer;
        }
        finally
        {
            var elapsedMs = Stopwatch.GetElapsedTime(start).TotalMilliseconds;
            LatencyHistogram.Record(elapsedMs);
        }
    }

    private static string BuildPrompt(string question, IReadOnlyList<VectorStoreRecord> chunks)
    {
        var context = string.Join("\n", chunks.Select(c => c.Text));
        return $"Context: {context}\n\nQuestion: {question}";
    }
}

// Modern .NET 9+ OpenTelemetry setup with automatic AI instrumentation:
//
// builder.Services.AddOpenTelemetry()
//     .WithAIGrpc(); // or WithAIHttp()
//
// This automatically instruments IChatClient and IEmbeddingGenerator calls
// without manual ActivitySource code in your RAG pipeline.

// Sample usage
var pipeline = new TracedRagPipeline(
    new OpenAIClient("your-api-key").AsEmbeddingGenerator("text-embedding-3-small"),
    new YourVectorStore(),
    new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini"));

using var _ = ActivitySource.StartActivity("app.request");
var answer = await pipeline.QueryAsync("How does DI work in ASP.NET Core?");
Console.WriteLine(answer);
